template <typename UnionPtrType>
BackgroundPtr Background::Clone() const {
  switch (tag_) {
    case Tag::kCustom:
      return NewCustom(
          mojo::Clone(data_.custom));
    case Tag::kBrave:
      return NewBrave(
          mojo::Clone(data_.brave));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, Background>::value>::type*>
bool Background::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kCustom:
      return mojo::Equals(data_.custom, other.data_.custom);
    case Tag::kBrave:
      return mojo::Equals(data_.brave, other.data_.brave);
  }

  return false;
}
